-- STAGED/UNEXECUTED. Owned disposable synthetic SQL only; no real Auth/SPIRE proof.
begin;
-- Owned disposable fixture only; requires original maintenance SUPERUSER so
-- SET SESSION AUTHORIZATION actually changes session_user. No real login secret.
create role axiom_local_custody_145_fixture_operator login noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls;
create role axiom_local_custody_145_fixture_bridge nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls;
grant axiom_local_custody_issuer to axiom_local_custody_145_fixture_operator with admin false,inherit false,set true;
-- The ordinary SQL harness has minimal auth.users only. This transaction-scoped
-- schema stand-in is created ONLY when absent; real GoTrue acceptance is separate.
-- Only an absent synthetic stand-in is created under its historical postgres
-- owner, so postgres-owned143 SECURITY DEFINER can read it. Existing GoTrue
-- auth.sessions is never altered or granted new permissions.
do $fixture145_auth$declare prior text:=current_user;begin
 if to_regclass('auth.sessions') is null then
  set local role postgres;
  create table auth.sessions(id uuid primary key,user_id uuid not null references auth.users(id),not_after timestamptz);
  execute format('set local role %I',prior);
 end if;
end $fixture145_auth$;
create function pg_temp.id(n int) returns uuid language sql immutable as $$select ('99143000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERTION: %',m;end if;end$$;
insert into auth.users(id,email) select pg_temp.id(n),'custody-'||n||'@example.invalid' from generate_series(1,5)n;
insert into public.users(id,email,is_axiom_internal) select pg_temp.id(n),'custody-'||n||'@example.invalid',n in(2,3) from generate_series(1,5)n;
insert into public.tenants(id,slug,name) values(pg_temp.id(11),'custody-143-a','Synthetic custody A'),(pg_temp.id(12),'custody-143-b','Synthetic custody B');
insert into public.tenant_users(tenant_id,user_id,role) values(pg_temp.id(11),pg_temp.id(1),'owner'),(pg_temp.id(11),pg_temp.id(2),'founder'),(pg_temp.id(11),pg_temp.id(3),'axiom_analyst'),(pg_temp.id(11),pg_temp.id(4),'viewer'),(pg_temp.id(12),pg_temp.id(5),'owner');
insert into auth.sessions(id,user_id,not_after) select pg_temp.id(100+n),pg_temp.id(n),null from generate_series(1,5)n;
insert into public.user_mfa_factors(id,user_id,factor_type,status,secret_encrypted) select pg_temp.id(40+n),pg_temp.id(n),'totp','active','synthetic-sealed' from generate_series(1,5)n;
insert into public.workload_identities(id,tenant_id,agent_name,spiffe_id,status) values(pg_temp.id(31),pg_temp.id(11),'parikshan','spiffe://local.axiom/agent/parikshan','active');
create function pg_temp.policy() returns jsonb language sql as $$select jsonb_build_object('version',1,'policyId',pg_temp.id(21),'tenantId',pg_temp.id(11),'mode','operator_managed','nominatedOperatorId',pg_temp.id(3),'targetWorkloadId',pg_temp.id(31),'servicePrincipals',jsonb_build_object('producer','spiffe://local.axiom/service/assessment-dispatch-producer','controller','spiffe://local.axiom/controller/assessment'),'validity',jsonb_build_object('kind','until_revoked','reviewDueAt',1),'actionClass','assessment_dispatch_key_custody','keyPolicy',jsonb_build_object('primary','axiom-local-dispatch://'||pg_temp.id(11)||'/'||pg_temp.id(21)||'/versions/1','readable',jsonb_build_array('axiom-local-dispatch://'||pg_temp.id(11)||'/'||pg_temp.id(21)||'/versions/1')),'keyPolicySha256','2e67deedbb81f6897d5f5a48a76734faaf79e6e86bd54285f03d9114a4e0f30b','deploymentBindingSha256',repeat('b',64),'reason','Explicit local custody limitation','acceptedLimitations',jsonb_build_array('hardware_backing_unverified'),'statutoryComplianceAsserted',false,'ownershipVerified',false)$$;
-- Above key-policy fingerprint is independently generated by frozen TS LocalKeyPolicy.
select pg_temp.ok(controller_security.local143_policy(controller_security.canonical_questionnaire_json(pg_temp.policy()))=pg_temp.policy(),'TS key fingerprint matches SQL canonical derivation');
-- Syntax parity only: actual issuer/peer must still pin the configured trusted principal.
do $$declare d text;k text;v jsonb;path text;begin
 foreach d in array array['..','.local','local.','-local','local-','a..b','LOCAL','a b',repeat('a',256)] loop
  foreach k in array array['producer','controller'] loop
   path:=case k when 'producer' then 'service/assessment-dispatch-producer' else 'controller/assessment' end;
   v:=jsonb_set(pg_temp.policy(),array['servicePrincipals',k],to_jsonb('spiffe://'||d||'/'||path));
   begin perform controller_security.local143_policy(controller_security.canonical_questionnaire_json(v));
    raise exception 'invalid custody service domain accepted';
   exception when invalid_parameter_value then null;end;
  end loop;
 end loop;
 foreach d in array array['a','local.axiom','a-b.c',repeat('a',255)] loop
  v:=jsonb_set(jsonb_set(pg_temp.policy(),'{servicePrincipals,producer}',to_jsonb('spiffe://'||d||'/service/assessment-dispatch-producer')),'{servicePrincipals,controller}',to_jsonb('spiffe://'||d||'/controller/assessment'));
  perform pg_temp.ok(controller_security.local143_policy(controller_security.canonical_questionnaire_json(v))=v,'canonical service domain accepted');
 end loop;
end$$;
create function pg_temp.request(k int,transition text,previous uuid default null) returns text language sql as $$select controller_security.canonical_questionnaire_json(jsonb_build_object('version',1,'operationKey',pg_temp.id(k),'transition',transition,'policyText',controller_security.canonical_questionnaire_json(pg_temp.policy()),'policySha256',encode(sha256(convert_to(controller_security.canonical_questionnaire_json(pg_temp.policy()),'UTF8')),'hex'),'previousEventId',previous,'nextReviewDueAt',case when transition='review' then to_jsonb(floor(extract(epoch from clock_timestamp())*1000)::bigint+86400000) else 'null'::jsonb end,'reason','Explicit synthetic custody decision','confirmed',true))$$;
create function pg_temp.challenge(actor int,request_text text) returns uuid language plpgsql as $$declare c uuid:=gen_random_uuid();r jsonb:=request_text::jsonb;binding text;begin
 binding:=encode(sha256(convert_to(controller_security.canonical_questionnaire_json(jsonb_build_array('axiom.local-custody.transition',1,pg_temp.id(11)::text,pg_temp.id(actor)::text,pg_temp.id(100+actor)::text,encode(sha256(convert_to(request_text,'UTF8')),'hex'))),'UTF8')),'hex');
 insert into public.mfa_challenges(id,user_id,tenant_id,factor_id,purpose,bound_resource_ref,bound_payload_sha256,created_at,expires_at,satisfied_at,consumed_at,consumed_for,satisfied_with) values(c,pg_temp.id(actor),pg_temp.id(11),pg_temp.id(40+actor),'local_custody_policy',r->>'operationKey',binding,clock_timestamp()-interval '2 seconds',clock_timestamp()+interval '4 minutes 50 seconds',clock_timestamp()-interval '1 second',clock_timestamp(),r->>'operationKey','totp');return c;
end$$;
create function pg_temp.write(request_text text,actor int,challenge uuid default null) returns jsonb language plpgsql as $$declare c uuid:=coalesce(challenge,pg_temp.challenge(actor,request_text));v jsonb;prior text:=current_user;begin
 set local role human_action_writer;v:=public.record_local_custody_policy_event(pg_temp.id(11),pg_temp.id(actor),pg_temp.id(100+actor),request_text,c);execute format('set local role %I',prior);return v;
 exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.refused(request_text text,actor int,code text default '42501',challenge uuid default null) returns void language plpgsql as $$declare n bigint;begin
 select count(*) into n from public.audit_ledger;
 begin perform pg_temp.write(request_text,actor,challenge);set constraints all immediate;exception when others then if sqlstate=code then perform pg_temp.ok((select count(*)=n from public.audit_ledger),'refusal leaves ledger unchanged');return;end if;raise;end;
 raise exception 'unexpected custody authorization';end$$;

create temporary table custody_saved(kind text primary key,v jsonb,request_text text);
insert into custody_saved values('request',pg_temp.write(pg_temp.request(61,'request'),1),pg_temp.request(61,'request'));
insert into custody_saved select 'approve',pg_temp.write(pg_temp.request(62,'approve',(v->>'eventId')::uuid),2),pg_temp.request(62,'approve',(v->>'eventId')::uuid) from custody_saved where kind='request';
insert into custody_saved select 'activate',pg_temp.write(pg_temp.request(63,'activate',(v->>'eventId')::uuid),3),pg_temp.request(63,'activate',(v->>'eventId')::uuid) from custody_saved where kind='approve';
set constraints all immediate;set constraints all deferred;
create temporary table issuer145_clock(n bigint);
insert into issuer145_clock values(floor(extract(epoch from clock_timestamp()))::bigint);
create function pg_temp.issue145(n int,kind text default 'controller',predecessor uuid default null) returns text language sql as $$select controller_security.canonical_questionnaire_json(jsonb_build_object(
 'version',1,'purpose','local-custody-credential-issue','credentialId',pg_temp.id(n),'tenantId',pg_temp.id(11),
 'policyId',pg_temp.id(21),'policySha256',encode(sha256(convert_to(controller_security.canonical_questionnaire_json(pg_temp.policy()),'UTF8')),'hex'),
 'activationEventId',(select (saved.v->>'eventId')::uuid from custody_saved saved where saved.kind='activate'),'activationEpoch',1,
 'configurationSha256',repeat('b',64),'workloadId',pg_temp.id(31),'principalKind',kind,
 'servicePrincipal',case kind when 'operator' then 'operator:'||pg_temp.id(3) else pg_temp.policy()->'servicePrincipals'->>kind end,
 'operatorId',case when kind='operator' then pg_temp.id(3) else null end,'predecessorId',predecessor,
 'issuedAt',(select c.n from issuer145_clock c),'expiresAt',(select c.n+3600 from issuer145_clock c),'reason','Reviewed synthetic credential issue'))$$;
create function pg_temp.revoke145(request_text text,why text default 'Reviewed synthetic emergency revocation') returns text language sql as $$select controller_security.canonical_questionnaire_json(jsonb_build_object('version',1,'purpose','local-custody-credential-revoke','credentialId',request_text::jsonb->>'credentialId','tenantId',request_text::jsonb->>'tenantId','issuanceSha256',encode(sha256(convert_to(request_text,'UTF8')),'hex'),'reason',why))$$;
create function pg_temp.invoke145(request_text text,purpose text default 'issue',digest_override text default null) returns jsonb language plpgsql as $$declare prior text:=current_user;result jsonb;digest text:=coalesce(digest_override,encode(sha256(convert_to(request_text,'UTF8')),'hex'));begin
 set local session authorization axiom_local_custody_145_fixture_operator;
 set local role axiom_local_custody_issuer;
 if purpose='issue' then result:=controller_security.issue_local_custody_credential(request_text,digest);
 elsif purpose='revoke' then result:=controller_security.revoke_local_custody_credential(request_text,digest);
 else result:=controller_security.local_custody_credential_status((request_text::jsonb->>'credentialId')::uuid,(request_text::jsonb->>'tenantId')::uuid,digest);end if;
 reset role;reset session authorization;execute format('set local role %I',prior);return result;
 exception when others then reset role;reset session authorization;execute format('set local role %I',prior);raise;end$$;
create function pg_temp.refuse145(request_text text,code text,purpose text default 'issue',digest_override text default null) returns void language plpgsql as $$declare counts bigint[];begin
 counts:=array[(select count(*) from controller_security.local_custody_credentials),(select count(*) from controller_security.local_custody_issuances),(select count(*) from controller_security.local_custody_revocations),(select count(*) from public.audit_ledger)];
 begin perform pg_temp.invoke145(request_text,purpose,digest_override);set constraints all immediate;exception when others then
  if sqlstate=code then perform pg_temp.ok(counts=array[(select count(*) from controller_security.local_custody_credentials),(select count(*) from controller_security.local_custody_issuances),(select count(*) from controller_security.local_custody_revocations),(select count(*) from public.audit_ledger)],'refusal creates zero credential/fact/ledger writes');return;end if;raise;end;
 raise exception 'unexpected local credential authorization';end$$;
create temporary table issuer145_saved(kind text primary key,request_text text,result jsonb);

-- Actual policy quorum and MFA receipts above, not hand-inserted policy events.
insert into issuer145_saved values('controller',pg_temp.issue145(201),pg_temp.invoke145(pg_temp.issue145(201)));
insert into issuer145_saved values('producer',pg_temp.issue145(202,'producer'),pg_temp.invoke145(pg_temp.issue145(202,'producer')));
insert into issuer145_saved values('operator',pg_temp.issue145(203,'operator'),pg_temp.invoke145(pg_temp.issue145(203,'operator')));
set constraints all immediate;set constraints all deferred;
select pg_temp.ok((select count(*)=3 from controller_security.local_custody_issuances where tenant_id=pg_temp.id(11)),'three least-privilege principal records issued');
select pg_temp.ok((select count(*)=3 from public.audit_ledger where tenant_id=pg_temp.id(11) and action_type::text='custody.local_credential_issued' and actor_type='system' and actor_id='axiom-local-custody-issuer'),'truthful system receipts, no fabricated human event');
select pg_temp.ok((select pg_temp.invoke145(request_text)=result from issuer145_saved where kind='controller'),'exact lost-response issue replay');
select pg_temp.ok((select pg_temp.invoke145(request_text,'status')=result from issuer145_saved where kind='controller'),'positive exact status reconciliation');
-- No direct registry, ledger or existing controller issuer capability expansion.
select pg_temp.ok(not has_table_privilege('axiom_local_custody_issuer','controller_security.local_custody_credentials','INSERT'),'issuer RPC only, no raw registry insertion');
select pg_temp.ok(not has_table_privilege('axiom_local_custody_issuer','controller_security.local_custody_issuances','INSERT'),'issuer cannot detach immutable fact');
select pg_temp.ok(not has_table_privilege('service_role','controller_security.local_custody_issuances','SELECT'),'shared service cannot read issuance metadata');
select pg_temp.ok(not has_function_privilege('axiom_controller_issuer','controller_security.issue_local_custody_credential(text,text)','EXECUTE'),'old controller issuer not widened');
select pg_temp.ok(not has_function_privilege('axiom_local_custody_issuer','public.append_ledger(uuid,uuid,actor_type,text,text,text,text,ledger_action_type,text,text,text,uuid,uuid,text,text,ledger_result,jsonb)','EXECUTE'),'no direct append permission');
-- JWT claims alone cannot confer a protected SQL administration role.
do $$declare text_request text:=pg_temp.issue145(204);digest text:=encode(sha256(convert_to(text_request,'UTF8')),'hex');prior text:=current_user;begin
 set local role service_role;perform set_config('request.jwt.claims','{"role":"axiom_local_custody_issuer"}',true);
 begin perform controller_security.issue_local_custody_credential(text_request,digest);raise exception 'claims-only issuer accepted';exception when insufficient_privilege then null;end;
 execute format('set local role %I',prior);
end$$;
-- Privileged maintenance identity cannot impersonate an external issuer merely
-- by SET ROLE; only the narrowly preprovisioned real LOGIN session is accepted.
do $$declare request text:=pg_temp.issue145(204);digest text:=encode(sha256(convert_to(request,'UTF8')),'hex');begin
 set local role axiom_local_custody_issuer;
 begin perform controller_security.issue_local_custody_credential(request,digest);raise exception 'maintenance session acted as issuer';exception when insufficient_privilege then null;end;
 reset role;
end$$;
-- Both direct and NOLOGIN-intermediate application SET paths poison authority.
do $$begin
 begin grant axiom_local_custody_145_fixture_operator to authenticator with admin false,inherit false,set true;
  perform pg_temp.invoke145(pg_temp.issue145(204));raise exception 'transitive application LOGIN path accepted';
 exception when insufficient_privilege then null;end;
 begin
  grant axiom_local_custody_145_fixture_operator to axiom_local_custody_145_fixture_bridge with admin false,inherit false,set true;
  grant axiom_local_custody_145_fixture_bridge to authenticator with admin false,inherit false,set true;
  perform pg_temp.invoke145(pg_temp.issue145(204));raise exception 'transitive application NOLOGIN path accepted';
 exception when insufficient_privilege then null;end;
end$$;
-- The maintenance-owned fixture helper can revoke membership while this very
-- session remains SET ROLE issuer. It is never part of production SQL145.
create function pg_temp.revoke_fixture_issuer145() returns void language plpgsql security definer set search_path='' as $$begin
 revoke axiom_local_custody_issuer from axiom_local_custody_145_fixture_operator;
end$$;
do $$declare request text:=(select request_text from issuer145_saved where kind='controller');digest text:=encode(sha256(convert_to(request,'UTF8')),'hex');begin
 set local session authorization axiom_local_custody_145_fixture_operator;
 set local role axiom_local_custody_issuer;
 perform pg_temp.revoke_fixture_issuer145();
 -- SET ROLE and function EXECUTE privileges persist; the explicit live login
 -- membership test must reject status, historical replay and credential writes.
 if current_setting('role')<>'axiom_local_custody_issuer' then raise exception 'stale-role fixture lost selected role';end if;
 begin perform controller_security.local_custody_credential_status((request::jsonb->>'credentialId')::uuid,(request::jsonb->>'tenantId')::uuid,digest);raise exception 'stale SET ROLE status accepted';exception when insufficient_privilege then null;end;
 begin perform controller_security.issue_local_custody_credential(request,digest);raise exception 'stale SET ROLE replay accepted';exception when insufficient_privilege then null;end;
 reset role;reset session authorization;
end$$;
grant axiom_local_custody_issuer to axiom_local_custody_145_fixture_operator with admin false,inherit false,set true;
-- Strict canonical representation, digests, field set and original time bounds.
select pg_temp.refuse145(pg_temp.issue145(204),'22023','issue',repeat('0',64));
select pg_temp.refuse145(' '||pg_temp.issue145(204),'22023');
select pg_temp.refuse145(replace(pg_temp.issue145(204),'"version":1','"version":1,"version":1'),'22023');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('token','must never be SQL')),'22023');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(201)::jsonb||jsonb_build_object('reason','Changed body')),'23505');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('configurationSha256',repeat('c',64))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('activationEpoch',2)),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('activationEventId',pg_temp.id(62))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('policySha256',repeat('f',64))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('tenantId',pg_temp.id(12))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('workloadId',pg_temp.id(30))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('servicePrincipal','spiffe://local.axiom/agent/parikshan')),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204,'operator')::jsonb||jsonb_build_object('operatorId',pg_temp.id(2))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('issuedAt',(select n+10000 from issuer145_clock),'expiresAt',(select n+11000 from issuer145_clock))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('issuedAt',(select n-20 from issuer145_clock),'expiresAt',(select n-10 from issuer145_clock))),'42501');
select pg_temp.refuse145(controller_security.canonical_questionnaire_json(pg_temp.issue145(204)::jsonb||jsonb_build_object('expiresAt',(select n+86401 from issuer145_clock))),'22023');
-- Every actual human in the authority chain must remain authorized at NEW issue.
do $$declare actor int;begin foreach actor in array array[1,2,3] loop
 begin
  update public.tenant_users set role='viewer' where tenant_id=pg_temp.id(11) and user_id=pg_temp.id(actor);
  perform pg_temp.invoke145(pg_temp.issue145(204));raise exception 'retired policy actor accepted';
 exception when insufficient_privilege then null;end;
 end loop;end$$;
do $$begin begin update public.users set is_axiom_internal=false where id=pg_temp.id(2);perform pg_temp.invoke145(pg_temp.issue145(204));raise exception 'noninternal founder accepted';exception when insufficient_privilege then null;end;end$$;
do $$begin begin update public.workload_identities set status='disabled' where id=pg_temp.id(31);perform pg_temp.invoke145(pg_temp.issue145(204));raise exception 'retired workload accepted';exception when insufficient_privilege then null;end;end$$;
-- Explicit predecessor rotation is same deployment/principal; original remains
-- valid until separate revocation. One predecessor cannot fork two successors.
insert into issuer145_saved values('rotated',pg_temp.issue145(205,'controller',pg_temp.id(201)),pg_temp.invoke145(pg_temp.issue145(205,'controller',pg_temp.id(201))));
select pg_temp.refuse145(pg_temp.issue145(206,'controller',pg_temp.id(201)),'23505');
