-- A failing ledger append rolls back the already inserted credential too.
create function pg_temp.refuse_issuer_receipt145() returns trigger language plpgsql as $$begin raise exception 'synthetic credential receipt refusal' using errcode='23514';end$$;
create trigger synthetic145_receipt_refusal before insert on public.audit_ledger for each row when(new.action_type::text='custody.local_credential_issued') execute function pg_temp.refuse_issuer_receipt145();
select pg_temp.refuse145(pg_temp.issue145(209),'23514');
drop trigger synthetic145_receipt_refusal on public.audit_ledger;
-- Revocation and exact historical reconciliation survive policy retirement.
insert into custody_saved select 'revoke',pg_temp.write(pg_temp.request(64,'revoke',(v->>'eventId')::uuid),1),pg_temp.request(64,'revoke',(v->>'eventId')::uuid) from custody_saved where kind='activate';
select pg_temp.refuse145(pg_temp.issue145(208),'42501');
select pg_temp.ok((select pg_temp.invoke145(request_text)->>'status'='active' from issuer145_saved where kind='controller'),'historical issue replay does not adopt current policy state');
insert into issuer145_saved select 'revoked',pg_temp.revoke145(request_text),pg_temp.invoke145(pg_temp.revoke145(request_text),'revoke') from issuer145_saved where kind='controller';
set constraints all immediate;set constraints all deferred;
select pg_temp.ok((select result->>'status'='revoked' and result->'revocationReceipt' is not null from issuer145_saved where kind='revoked'),'positive irreversible revocation receipt');
select pg_temp.ok((select pg_temp.invoke145(request_text,'revoke')=result from issuer145_saved where kind='revoked'),'exact lost-response revoke replay');
select pg_temp.ok((select pg_temp.invoke145(request_text)->>'status'='revoked' from issuer145_saved where kind='controller'),'issue retry never unrevokes or refreshes expiry');
select pg_temp.refuse145((select pg_temp.revoke145(request_text,'Changed reason') from issuer145_saved where kind='controller'),'23505','revoke');
-- SQL143 credential immutability and145 fact/history guards stay in force.
do $$begin
 begin update controller_security.local_custody_credentials set revoked_at=null where id=pg_temp.id(201);raise exception 'credential unrevoked';exception when insufficient_privilege then null;end;
 begin update controller_security.local_custody_issuances set request_sha256=repeat('d',64) where credential_id=pg_temp.id(201);raise exception 'issuance changed';exception when insufficient_privilege then null;end;
 begin delete from controller_security.local_custody_revocations where credential_id=pg_temp.id(201);raise exception 'revocation deleted';exception when insufficient_privilege then null;end;
 begin truncate controller_security.local_custody_revocations;raise exception 'revocation truncated';exception when insufficient_privilege then null;end;
 begin
  alter table controller_security.local_custody_revocations drop constraint local_custody_revocations_tenant_id_credential_id_fkey;
  alter table controller_security.local_custody_revocations drop constraint local_custody_revocations_credential_id_fkey;
  truncate controller_security.local_custody_issuances;raise exception 'issuance parent guard missing';
 exception when insufficient_privilege then null;end;
 -- A naked system/agent receipt has no reciprocal private issuance fact.
 begin perform public.append_ledger(pg_temp.id(11),pg_temp.id(250),'system','axiom-local-custody-issuer',null,null,null,'custody.local_credential_issued',pg_temp.id(250)::text,repeat('a',64),repeat('b',64),null,null,null,null,'success','{}');set constraints all immediate;raise exception 'orphan issuer ledger committed';exception when check_violation then null;end;
 -- An issued credential cannot acquire a detached revocation timestamp.
 begin update controller_security.local_custody_credentials set revoked_at=clock_timestamp() where id=pg_temp.id(202);set constraints all immediate;raise exception 'unreceipted credential revoked';exception when check_violation then null;end;
end$$;
select pg_temp.ok(not exists(select 1 from controller_security.local_custody_issuances where credential_id=pg_temp.id(250)),'orphan receipt failure atomic');
select pg_temp.ok(not exists(select 1 from controller_security.local_custody_credentials where id=pg_temp.id(208)),'refused new authority absent');
select 'SQL145 protected credential administration fixture passed (synthetic, no token mint/realAuth acceptance)' as result;
rollback;
